define({"topics":[{"title":"Creating local users","shortdesc":"<p class=\"shortdesc\">Configure the local users' settings.<\/p>","href":"t_CreatingLocalUsers_4.html","attributes":{"data-id":"id_2012155"},"menu":{"hasChildren":false},"tocID":"id_2012155-d46e111703","topics":[]},{"title":"Setting up enterprise authentication","shortdesc":"<p class=\"shortdesc\">Enterprise Authorization with encrypted communication using Transfer Layer Security (TLS) and certificates is available for software 29 and later. If the facility IT desires, TLS certificates are required to establish this encryption.<\/p>","href":"t_SettingUpEnterpriseAuthentication_4.html","attributes":{"data-id":"id_2012154"},"menu":{"hasChildren":false},"tocID":"id_2012154-d46e111807","topics":[]},{"title":"Logging on and off","shortdesc":"<p class=\"shortdesc\">Use this procedure to log on and off the system.<\/p>","href":"t_UserInstructions_4.html","attributes":{"data-id":"id_2011694"},"menu":{"hasChildren":false},"tocID":"id_2011694-d46e111911","topics":[]},{"title":"<span class=\"ph\" id=\"_Toc473119580\">Configure user accounts for Role Based access controls<\/span>","shortdesc":"<p class=\"shortdesc\"\/>","href":"t_Enable_Authorization_role-based_access_control_3.html","attributes":{"data-id":"id_2021947"},"menu":{"hasChildren":false},"tocID":"id_2021947-d46e112015","topics":[]},{"title":"Configuring password controls","shortdesc":"<p class=\"shortdesc\">Configure password controls available on the MR system that apply to the local users.<\/p>","href":"t_ConfiguringPasswordControls_3.html","attributes":{"data-id":"id_2024233"},"menu":{"hasChildren":false},"tocID":"id_2024233-d46e112119","topics":[]},{"title":"Managing default users","shortdesc":"<p class=\"shortdesc\">The system includes default users who are managed by the site and are not required to be active. The users cannot be deleted, but they can be disabled (locked).<\/p>","href":"t_ManagingDefaultUsers_3.html","attributes":{"data-id":"id_2024235"},"menu":{"hasChildren":false},"tocID":"id_2024235-d46e112223","topics":[]},{"title":"Creating a customized logon message","shortdesc":"<p class=\"shortdesc\">The MR system can be configured to display a custom system message to be displayed on the logon screen.<\/p>","href":"t_CreatingACustomizedLogonMessage_3.html","attributes":{"data-id":"id_2024236"},"menu":{"hasChildren":false},"tocID":"id_2024236-d46e112327","topics":[]},{"title":"Enabling or disabling emergency logon authority","shortdesc":"<p class=\"shortdesc\">Emergency logon lets the user access the MR applications without logging on using a password. This may not be desired depending on the security level required at your site.<\/p>","href":"t_ConfigureForEnablingEmergencyLogin_4.html","attributes":{"data-id":"id_2011693"},"menu":{"hasChildren":false},"tocID":"id_2011693-d46e112431","topics":[]}]});